window.skillUpVascularBundleTypesQuestions=[
{q:"A vascular bundle is composed primarily of:",o:["Xylem and phloem","Epidermis and cortex","Palisade and spongy tissue","Endodermis and pericycle"],a:1,e:"Vascular bundles contain the conducting tissues xylem and phloem."},
{q:"A vascular bundle with xylem and phloem on different radii is called:",o:["Radial","Conjoint","Concentric","Amphivasal"],a:1,e:"In radial bundles, xylem and phloem occupy separate radii, as commonly seen in roots."},
{q:"A vascular bundle with xylem and phloem on the same radius is:",o:["Conjoint","Radial","Concentric","Amphicribral"],a:1,e:"Conjoint bundles have xylem and phloem together on the same radius."},
{q:"Vascular bundles of a typical dicot stem are generally:",o:["Conjoint, collateral and open","Radial and closed","Concentric and closed","Bicollateral and radial"],a:1,e:"Dicot stem bundles are commonly conjoint, collateral and open because cambium is present."},
{q:"Vascular bundles of a typical monocot stem are generally:",o:["Conjoint, collateral and closed","Radial and open","Concentric and open","Bicollateral and open"],a:1,e:"Monocot stem bundles are generally conjoint, collateral and closed."},
{q:"An open vascular bundle contains:",o:["Cambium","No phloem","No xylem","Only parenchyma"],a:1,e:"An open bundle has a cambial strip between xylem and phloem."},
{q:"A closed vascular bundle lacks:",o:["Vascular cambium between xylem and phloem","Xylem","Phloem","Bundle sheath"],a:1,e:"Closed bundles do not have a vascular cambium capable of producing secondary tissues."},
{q:"In a collateral vascular bundle, phloem lies:",o:["Outside the xylem","Inside the xylem","At the centre of xylem","On a separate radius"],a:1,e:"Collateral bundles have phloem external and xylem internal."},
{q:"A bicollateral vascular bundle has:",o:["Phloem on both sides of xylem","Xylem on both sides of phloem","Only xylem","Only phloem"],a:1,e:"Bicollateral bundles contain external and internal phloem with xylem between them."},
{q:"Bicollateral vascular bundles are characteristic of:",o:["Cucurbita and some related plants","Maize only","Typical grasses only","Most roots only"],a:1,e:"Cucurbita is a classic example with bicollateral vascular bundles."},
{q:"A concentric vascular bundle has:",o:["One vascular tissue completely surrounding the other","Xylem and phloem on separate radii","Only xylem","Only phloem"],a:1,e:"In concentric bundles, one conducting tissue forms a complete ring around the other."},
{q:"When phloem surrounds xylem in a concentric bundle, it is called:",o:["Amphicribral","Amphivasal","Collateral","Radial"],a:1,e:"Amphicribral bundles have phloem completely surrounding xylem."},
{q:"When xylem surrounds phloem in a concentric bundle, it is called:",o:["Amphivasal","Amphicribral","Collateral","Bicollateral"],a:1,e:"Amphivasal bundles have xylem surrounding the phloem."},
{q:"A radial vascular bundle is typical of:",o:["Roots","Typical dicot stems","Typical monocot stems","Leaves only"],a:1,e:"Root vascular systems commonly have xylem and phloem arranged on alternate radii."},
{q:"In a radial bundle, xylem and phloem are:",o:["On different radii","On the same radius","Always concentric","Absent"],a:1,e:"Radial arrangement separates xylem and phloem into different radial strands."},
{q:"The xylem of a typical root is commonly:",o:["Exarch","Endarch","Mesarch only","Centrarch"],a:1,e:"Root xylem is typically exarch, with protoxylem toward the outside."},
{q:"The xylem of a typical stem is commonly:",o:["Endarch","Exarch","Centrarch","Mesarch only"],a:1,e:"Stem xylem is generally endarch, with protoxylem toward the centre."},
{q:"A vascular bundle containing cambium is described as:",o:["Open","Closed","Radial","Concentric"],a:1,e:"The presence of vascular cambium makes a conjoint bundle open."},
{q:"The cambium in an open collateral bundle is located:",o:["Between xylem and phloem","Outside the epidermis","Inside the pith only","Between cortex and epidermis"],a:1,e:"Vascular cambium occupies the boundary between xylem and phloem."},
{q:"Secondary growth is generally associated with:",o:["Open vascular bundles containing cambium","Closed bundles only","Radial bundles only","Bundles lacking xylem"],a:1,e:"Cambium in open bundles can produce secondary vascular tissues."},
{q:"Which bundle type is commonly found in a monocot stem?",o:["Collateral and closed","Radial and open","Bicollateral and open","Amphicribral"],a:1,e:"Monocot stem bundles are commonly collateral and closed."},
{q:"Which bundle type is commonly found in a dicot root?",o:["Radial","Conjoint collateral","Bicollateral only","Amphivasal"],a:1,e:"Dicot roots typically show radial vascular arrangement."},
{q:"In a conjoint vascular bundle, xylem and phloem occur:",o:["Together in the same bundle","On completely separate radii","Only in the cortex","Only in the pith"],a:1,e:"Conjoint means xylem and phloem are present together within the same vascular bundle."},
{q:"The vascular bundles of leaves are usually:",o:["Conjoint","Radial","Always bicollateral","Always concentric"],a:1,e:"Leaf vascular bundles are generally conjoint, with xylem and phloem in the same bundle."},
{q:"A bundle in which xylem and phloem are arranged side by side is:",o:["Collateral","Radial","Amphicribral","Amphivasal"],a:1,e:"Collateral arrangement places phloem toward the outside and xylem toward the inside."},
{q:"Which tissue is normally located toward the outer side of a collateral stem bundle?",o:["Phloem","Xylem","Pith","Endodermis"],a:1,e:"Phloem is external to xylem in a typical collateral bundle."},
{q:"Which vascular bundle type contains phloem both externally and internally?",o:["Bicollateral","Collateral","Radial","Amphivasal"],a:1,e:"Bicollateral bundles have phloem on both sides of the xylem."},
{q:"A vascular bundle can be classified according to:",o:["Relative arrangement of xylem and phloem and presence of cambium","Only its colour","Only its size","Only its cell count"],a:1,e:"Bundle classification depends on the arrangement of conducting tissues and cambium status."},
{q:"Which pair is correctly matched?",o:["Radial — typical root bundle arrangement","Collateral — xylem and phloem on separate radii","Amphicribral — xylem surrounds phloem","Closed — cambium present"],a:1,e:"Radial arrangement is characteristic of roots."},
{q:"The best comparison is:",o:["Dicot stem: open collateral; monocot stem: closed collateral","Dicot stem: radial; monocot stem: open radial","Dicot stem: amphivasal; monocot stem: bicollateral","Both always have identical bundle types"],a:1,e:"Typical dicot stems have open collateral bundles, whereas typical monocot stems have closed collateral bundles."}
];